def two_sum(nums: list[int], target: int) -> list[int]:
    seen: dict[int, int] = {}
    for i, x in enumerate(nums):
        # najpierw sprawdzamy dopelnienie, potem wstawiamy — unika uzycia elementu dwukrotnie
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

def length_of_longest_substring(s: str) -> int:
    last: dict[str, int] = {}
    best = 0
    left = 0
    for right, c in enumerate(s):
        if c in last and last[c] >= left:
            left = last[c] + 1  # skok za poprzednie wystapienie
        last[c] = right
        best = max(best, right - left + 1)
    return best

def min_distance(word1: str, word2: str) -> int:
    n, m = len(word1), len(word2)
    dp = list(range(m + 1))  # dp[0][j] = j
    for i in range(1, n + 1):
        prev_diag = dp[0]
        dp[0] = i
        for j in range(1, m + 1):
            cur = dp[j]
            if word1[i - 1] == word2[j - 1]:
                dp[j] = prev_diag
            else:
                dp[j] = 1 + min(prev_diag, dp[j], dp[j - 1])
            prev_diag = cur
    return dp[m]

def min_eating_speed(piles: list[int], h: int) -> int:
    def hours_needed(k: int) -> int:
        # ceil(p / k) bez floatow
        return sum((p + k - 1) // k for p in piles)

    lo, hi = 1, max(piles)
    while lo < hi:
        mid = (lo + hi) // 2  # zaokraglenie w dol pasuje do hi = mid
        if hours_needed(mid) <= h:
            hi = mid
        else:
            lo = mid + 1
    return lo

def num_islands(grid: list[list[str]]) -> int:
    from collections import deque
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '1':
                continue
            count += 1
            grid[r][c] = '0'  # oznaczamy przy wkladaniu
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == '1':
                        grid[ny][nx] = '0'
                        q.append((ny, nx))
    return count

def network_delay_time(times: list[list[int]], n: int, k: int) -> int:
    import heapq
    adj: list[list[tuple[int, int]]] = [[] for _ in range(n + 1)]
    for u, v, w in times:
        adj[u].append((v, w))
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[k] = 0
    pq: list[tuple[int, int]] = [(0, k)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue  # przestarzaly wpis
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    worst = max(dist[1:])
    return -1 if worst == INF else int(worst)

def coin_change(coins: list[int], amount: int) -> int:
    INF = amount + 1  # wiecej monet niz to niemozliwe
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

def length_of_lis(nums: list[int]) -> int:
    import bisect
    tails: list[int] = []
    for x in nums:
        pos = bisect.bisect_left(tails, x)  # lower_bound: scisle rosnacy
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
    return len(tails)

def hungarian(cost: list[list[int]]) -> int:
    """Minimalny koszt przydzialu, macierz n x n, O(n^3). Indeksowanie od 1."""
    n = len(cost)
    INF = float('inf')
    u = [0] * (n + 1)
    v = [0] * (n + 1)
    p = [0] * (n + 1)    # p[j] = wiersz skojarzony z kolumna j
    way = [0] * (n + 1)
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (n + 1)
        used = [False] * (n + 1)
        while True:
            used[j0] = True
            i0, delta, j1 = p[j0], INF, -1
            for j in range(1, n + 1):
                if used[j]:
                    continue
                cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                if cur < minv[j]:
                    minv[j], way[j] = cur, j0
                if minv[j] < delta:
                    delta, j1 = minv[j], j
            for j in range(n + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while j0:  # odtworzenie sciezki powiekszajacej
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
    return sum(cost[p[j] - 1][j - 1] for j in range(1, n + 1))

def max_subarray(nums: list[int]) -> int:
    best = cur = nums[0]  # niepusty podciag: start od pierwszego elementu
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    intervals.sort(key=lambda it: it[0])
    out: list[list[int]] = []
    for start, end in intervals:
        if out and start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)  # max, nie samo end
        else:
            out.append([start, end])
    return out

def ladder_length(begin_word: str, end_word: str, word_list: list[str]) -> int:
    from collections import deque
    words = set(word_list)
    if end_word not in words:
        return 0
    q = deque([(begin_word, 1)])
    words.discard(begin_word)
    while q:
        word, steps = q.popleft()
        if word == end_word:
            return steps
        for i in range(len(word)):
            for ch in 'abcdefghijklmnopqrstuvwxyz':
                nxt = word[:i] + ch + word[i + 1:]
                if nxt in words:
                    words.remove(nxt)  # odwiedzone przy wkladaniu
                    q.append((nxt, steps + 1))
    return 0
